#!/usr/bin/env node
// ---------------------------------------------------------------------------
// bundle.js — 零依赖构建：把分层 src/*.js 按依赖顺序拼接成单文件函数体，
// 并把 config/default.json 注入为 __CONFIG__，产出 dist/plugin.js。
//
// 产出的 dist/plugin.js 是一段“函数体”（以 `return {...}` 结尾），
// 可直接作为 DSH 动态插件的 host code，也可内联进 agent preset。
// ---------------------------------------------------------------------------

const fs = require('fs')
const path = require('path')

const root = path.resolve(__dirname, '..')
const configPath = path.join(root, 'config', 'default.json')
const config = JSON.parse(fs.readFileSync(configPath, 'utf8'))

// 依赖顺序：capture -> probe -> report -> reconstruct -> command -> index（函数体结尾）。
const modules = [
  'src/core/capture.js',
  'src/core/probe.js',
  'src/core/report.js',
  'src/core/reconstruct.js',
  'src/command.js',
  'src/index.js'
]

const banner = '// Generated by build/bundle.js — do not edit directly. Source: src/ + config/default.json\n'
let body = banner + 'const __CONFIG__ = ' + JSON.stringify(config) + ';\n'

for (const rel of modules) {
  const src = fs.readFileSync(path.join(root, rel), 'utf8')
  body += '\n// ===== ' + rel + ' =====\n' + src + '\n'
}

const distDir = path.join(root, 'dist')
fs.mkdirSync(distDir, { recursive: true })

// 1) 函数体版：直接作为动态插件的 host code（以 `return {...}` 结尾）。
const jsPath = path.join(distDir, 'plugin.js')
fs.writeFileSync(jsPath, body)

// 2) CommonJS 模块版：供 agent preset 通过相对路径 specifier 加载
//    （cordis.yml 里 `name: ./plugin.cjs`，module.exports = plugin 对象）。
const cjs = '// Generated by build/bundle.js — do not edit directly.\n' +
  "'use strict'\nmodule.exports = (function () {\n" + body + '\n})()\n'
const cjsPath = path.join(distDir, 'plugin.cjs')
fs.writeFileSync(cjsPath, cjs)

console.log('built dist/plugin.js (' + body.length + ' bytes)')
console.log('built dist/plugin.cjs (' + cjs.length + ' bytes)')
